                                  'portanto o fator do período é taxa_bps * meses / 10000. O '
                                  'resultado\n'
                                  'é truncado para baixo (divisão inteira), garantindo que todos '
                                  'os\n'
                                  'valores permaneçam centavos inteiros — nunca float.\n'
                                  '"""\n'
                                  '\n'
                                  '\n'
                                  'def juros_simples(principal, taxa_bps, meses):\n'
                                  '    """Juros simples: principal * taxa_bps * meses // '
                                  '10000."""\n'
                                  '    if principal < 0 or taxa_bps < 0 or meses < 0:\n'
                                  '        raise ValueError("parametros devem ser nao-negativos")\n'
                                  '    return (principal * taxa_bps * meses) // 10000\n'
                                  '\n'
                                  '\n'
                                  'def montante(principal, taxa_bps, meses):\n'
                                  '    """Principal acrescido dos juros simples do período."""\n'
