                                '    texto = '
                                '"caixa;credito;1000\\nbanco;credito;250\\ncaixa;debito;300"\n'
                                '    esperado = "EXTRATO\\nbanco: R$ 2,50\\ncaixa: R$ '
                                '7,00\\nTOTAL: R$ 9,50"\n'
