                                       'Cada entrada mapeia (estado_origem, evento) -> '
                                       'estado_destino.\n'
                                       'Transições ausentes da tabela são inválidas.\n'
                                       '"""\n'
                                       'from estados import CANCELADO, ENTREGUE, ENVIADO, NOVO, '
                                       'PAGO, SEPARADO\n'
                                       '\n'
                                       'TRANSICOES = {\n'
                                       '    (NOVO, "pagar"): PAGO,\n'
                                       '    (PAGO, "separar"): SEPARADO,\n'
                                       '    (SEPARADO, "enviar"): ENVIADO,\n'
                                       '    (ENVIADO, "entregar"): ENTREGUE,\n'
                                       '    (NOVO, "cancelar"): CANCELADO,\n'
                                       '    (PAGO, "cancelar"): CANCELADO,\n'
                                       '    (SEPARADO, "cancelar"): CANCELADO,\n'
                                       '}\n'
                                       '\n'
                                       '\n'
                                       'def destino(estado, evento):\n'
                                       '    """Estado de destino da transição, ou None se não '
                                       'permitida."""\n'
                                       '    return TRANSICOES.get((estado, evento))\n'
                                       '\n'
                                       '\n'
                                       'def transicao_valida(estado, evento):\n'
                                       '    """True se o par (estado, evento) está na tabela."""\n'
                                       '    return (estado, evento) in TRANSICOES\n'
                                       '\n'
