                                'deterministico."""\n'
                                '\n'
                                '\n'
                                'def conta(tokens: list[str]) -> dict[str, int]:\n'
                                '    """Frequencia absoluta de cada token, em ordem de primeira '
                                'ocorrencia."""\n'
                                '    freq: dict[str, int] = {}\n'
                                '    for token in tokens:\n'
                                '        freq[token] = freq.get(token, 0) + 1\n'
                                '    return freq\n'
                                '\n'
                                '\n'
                                'def top_k(freq: dict[str, int], k: int) -> list[tuple[str, '
                                'int]]:\n'
                                '    """Top-k por frequencia decrescente; empate resolvido em '
                                'ordem alfabetica."""\n'
                                '    itens = sorted(freq.items(), key=lambda par: (-par[1], '
                                'par[0]))\n'
                                '    return itens[:k]\n'
                                '\n'
                                '\n'
                                'def total_tokens(freq: dict[str, int]) -> int:\n'
                                '    """Soma de todas as frequencias."""\n'
                                '    return sum(freq.values())\n'
                                '\n'
                                '\n'
                                'def vocabulario(freq: dict[str, int]) -> list[str]:\n'
                                '    """Palavras distintas em ordem alfabetica."""\n'
                                '    return sorted(freq)\n'
                                '\n'
                                '\n'
