                                'int]:\n'
                                '    """Frequencia de pares consecutivos de tokens."""\n'
                                '    freq: dict[tuple[str, str], int] = {}\n'
                                '    for i in range(len(tokens) - 1):\n'
                                '        par = (tokens[i], tokens[i + 1])\n'
                                '        freq[par] = freq.get(par, 0) + 1\n'
                                '    return freq\n'
                                '\n'
                                '\n'
                                'def percentual_inteiro(freq: dict[str, int]) -> dict[str, int]:\n'
