                                '    tokens = []\n'
                                '    for bruto in texto.split():\n'
                                '        token = bruto.strip(PONTUACAO)\n'
                                '        token = token.lower()\n'
                                '        if token:\n'
                                '            tokens.append(token)\n'
                                '    return tokens\n'
