STRATA: dict[str, str] = {t["task_id"]: t["family"] for t in TASKS}

__all__ = ["TASKS", "STRATA"]


def get_task(task_id: str) -> dict:
    for t in TASKS:
        if t["task_id"] == task_id:
            return t
    raise KeyError(task_id)
